#!/bin/bash
# the S2 bench (from S1's): ONE page (test&scene=12, the fake), q pinned, 8 s warm, a cold call discarded, then 3 interleaved triples
# benchFluid(300,null,'pool') / (300,null,'bands') (K2 default: SWIRL 0 — the branch not taken) / bands with SWIRL .8 and MS.sub .8 held (the branch taken)
cd /home/toma/Documents/Kraftek/RetinaRave-wt-fluid2 || exit 1
SHIP=$(node -e "import('./assets/core/fluid/inject2.js').then(m=>console.log(m.K.KICK_SHAPE))")
E='{"eval":"CARD.benchFluid(300,null,\"pool\").toFixed(3)"},{"eval":"(CARD.fluid.K2.KICK_SHAPE='$SHIP',CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" ship \"+JSON.stringify(CARD.fluid.kick))"},{"eval":"(CARD.fluid.K2.KICK_SHAPE=0,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" shape0 \"+JSON.stringify(CARD.fluid.kick))"},{"eval":"(CARD.fluid.K2.KICK_SHAPE='$SHIP',CARD.MS.kickEvt=1,CARD.MS.kickAmp=0.9,CARD.MS.kickAge=0,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" ship-kick-every-step \"+JSON.stringify(CARD.fluid.kick)+\" n \"+CARD.fluid.nSplat)"}'
GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=12" "[{\"until\":\"window.CARD\"},{\"eval\":\"setInterval(()=>CARD.Q.q=0.95,16);'pinned'\"},{\"wait\":8000},{\"eval\":\"CARD.benchFluid(300,null,'pool').toFixed(3)+' cold'\"},$E,$E,$E,{\"eval\":\"(CARD.fluid.K2.KICK_SHAPE='$SHIP',CARD.bench(0,300).toFixed(3)+' nav')\"},{\"eval\":\"JSON.stringify({tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],q:CARD.Q.q,g:CARD.fluid.grammar,errs:CARD.ERRS})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
uptime
echo "== MOBILE=1 tier 0: scene 13 alive + the bench at tier 0 (the swirl held)"
MOBILE=1 GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=13" "[{\"until\":\"window.CARD\"},{\"wait\":4000},{\"eval\":\"JSON.stringify({sc:CARD.SC.cur,g:CARD.fluid.grammar,tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],errs:CARD.ERRS,bad:CARD.nonFinite(),frameN:CARD.frameN,heave:CARD.fluid.heave})\"},{\"eval\":\"CARD.benchFluid(300,null,'bands').toFixed(3)+' bands default'\"},{\"eval\":\"(CARD.fluid.K2.SWIRL=0.8,CARD.MS.sub=0.8,CARD.benchFluid(300,null,'bands').toFixed(3)+' bands swirl '+CARD.fluid.swirl.toFixed(3))\"},{\"eval\":\"CARD.benchFluid(300,null,'pool').toFixed(3)+' pool'\"},{\"shot\":\"s2-mobile-s13\"},{\"eval\":\"JSON.stringify({errs:CARD.ERRS,bad:CARD.nonFinite(),tier:CARD.fluid.tier})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
